//! `smoother` against the real nav2_velocity_smoother node
//! (tests/data/smoother.json, regenerated by tests/oracle/run_oracle.sh
//! smoother): every command, timer firing and publication replayed in order,
//! and the yaml the robot's parameters come from.

mod common;

use common::{assert_close, f};
use mower_nav_core::geometry::Twist2D;
use mower_nav_core::smoother::{InputError, TwistStamped, VelocitySmoother, VelocitySmootherParams};
use serde_json::Value;

/// `common::load`, but with every float read correctly rounded. serde_json
/// without its `float_roundtrip` feature reads about one float in ten of
/// these files one ulp off, which flips boundary cases (the xy tolerance
/// circle); serde_yaml parses JSON (it is YAML) with `str::parse::<f64>`.
fn load_exact(name: &str) -> Value {
    let path = format!("{}/tests/data/{}", env!("CARGO_MANIFEST_DIR"), name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {path}: {e} (run tests/oracle/run_oracle.sh)"));
    serde_yaml::from_str(&text).unwrap_or_else(|e| panic!("cannot parse {path}: {e}"))
}

/// The scenarios run on the `velocity_smoother` section of the yaml.
const PRODUCTION: [&str; 5] = ["steps", "timeout", "stamps", "negative_stamp", "random_robot"];

fn num(v: &Value) -> f64 {
    match v.as_str() {
        Some("nan") => f64::NAN,
        Some("inf") => f64::INFINITY,
        Some("-inf") => f64::NEG_INFINITY,
        Some(s) => panic!("number expected, got {s}"),
        None => f(v),
    }
}

/// `[linear x y z, angular x y z]`.
fn v6(v: &Value) -> [f64; 6] {
    let a = v.as_array().unwrap();
    std::array::from_fn(|i| num(&a[i]))
}

fn arr3(v: &Value) -> [f64; 3] {
    let a = v.as_array().unwrap();
    std::array::from_fn(|i| f(&a[i]))
}

fn b(v: &Value) -> bool {
    v.as_bool().unwrap_or_else(|| panic!("bool expected, got {v}"))
}

/// The parameters as the node read them; those `on_configure` had not
/// declared when it failed stay at their defaults.
fn params(p: &Value) -> VelocitySmootherParams {
    let mut out = VelocitySmootherParams {
        max_velocity: arr3(&p["max_velocity"]),
        min_velocity: arr3(&p["min_velocity"]),
        max_accel: arr3(&p["max_accel"]),
        max_decel: arr3(&p["max_decel"]),
        ..VelocitySmootherParams::default()
    };
    if b(&p["configured"]) {
        assert_eq!(p["feedback"].as_str(), Some("OPEN_LOOP"));
        assert_eq!(p["enable_stamped_cmd_vel"].as_bool(), Some(true));
        out.smoothing_frequency = f(&p["smoothing_frequency"]);
        out.scale_velocities = b(&p["scale_velocities"]);
        out.deadband_velocity = arr3(&p["deadband_velocity"]);
        out.velocity_timeout = f(&p["velocity_timeout"]);
        out.stamp_smoothed_velocity_with_smoothing_time = b(&p["stamp_smoothed_velocity_with_smoothing_time"]);
    }
    out
}

fn message(stamp_ns: i64, frame: &str, v: [f64; 6]) -> TwistStamped {
    TwistStamped {
        stamp_ns,
        frame_id: frame.to_string(),
        twist: Twist2D::new(v[0], v[1], v[5]),
        other: [v[2], v[3], v[4]],
    }
}

#[test]
fn oracle_configurations_are_the_yaml_and_the_defaults() {
    let d = load_exact("smoother.json");
    for s in d["scenarios"].as_array().unwrap() {
        let name = s["name"].as_str().unwrap();
        let p = params(&s["params"]);
        if PRODUCTION.contains(&name) {
            assert_eq!(p, VelocitySmootherParams::mower(), "{name}");
        }
        if name == "defaults" {
            assert_eq!(p, VelocitySmootherParams::default(), "{name}");
        }
    }
}

#[test]
fn configure_checks_match_on_configure() {
    let d = load_exact("smoother.json");
    for c in d["configurations"].as_array().unwrap() {
        let r = VelocitySmoother::new(params(c));
        assert_eq!(r.is_ok(), b(&c["configured"]), "{c}: {:?}", r.err());
        if let Ok(s) = r {
            assert_eq!(s.timer_period_ns(), c["timer_period_ns"].as_i64().unwrap());
        }
    }
}

#[test]
fn smoother_matches_velocity_smoother_node() {
    let d = load_exact("smoother.json");
    for s in d["scenarios"].as_array().unwrap() {
        let name = s["name"].as_str().unwrap();
        let mut smoother = VelocitySmoother::new(params(&s["params"])).unwrap();
        assert_eq!(smoother.timer_period_ns(), s["params"]["timer_period_ns"].as_i64().unwrap(), "{name}");
        let (mut published, mut silent) = (0, 0);
        for (i, e) in s["events"].as_array().unwrap().iter().enumerate() {
            let e = e.as_array().unwrap();
            let what = format!("{name} event {i} {e:?}");
            let t = e[1].as_i64().unwrap();
            match e[0].as_str().unwrap() {
                "in" => {
                    let msg = message(e[2].as_i64().unwrap(), e[3].as_str().unwrap(), v6(&e[4]));
                    let r = smoother.input_command(&msg, t);
                    if b(&e[6]) {
                        // upstream throws out of the callback (the node dies)
                        assert_eq!(r, Err(InputError::NegativeStamp), "{what}");
                    } else if b(&e[5]) {
                        assert_eq!(r, Ok(()), "{what}");
                    } else {
                        assert_eq!(r, Err(InputError::NonFinite), "{what}");
                    }
                }
                "in_twist" => {
                    let v = v6(&e[2]);
                    let r = smoother.input_command_unstamped(&Twist2D::new(v[0], v[1], v[5]), [v[2], v[3], v[4]], t);
                    assert_eq!(r.is_ok(), b(&e[3]), "{what}");
                }
                "tick" => {
                    let out = smoother.tick(t);
                    assert_eq!(out.is_some(), !e[2].is_null(), "{what}: published");
                    if let Some(out) = out {
                        let o = e[2].as_array().unwrap();
                        assert_eq!(out.stamp_ns, o[0].as_i64().unwrap(), "{what}: stamp");
                        assert_eq!(out.frame_id, o[1].as_str().unwrap(), "{what}: frame_id");
                        let v = v6(&o[2]);
                        assert_close(out.twist.x, v[0], &format!("{what}: linear.x"));
                        assert_close(out.twist.y, v[1], &format!("{what}: linear.y"));
                        assert_close(out.twist.theta, v[5], &format!("{what}: angular.z"));
                        assert_eq!(out.other, [v[2], v[3], v[4]], "{what}: other axes");
                        published += 1;
                    } else {
                        silent += 1;
                    }
                    assert_eq!(smoother.stopped(), b(&e[3]), "{what}: stopped");
                }
                other => panic!("unknown event {other}"),
            }
        }
        if name != "negative_stamp" {
            assert!(published > 100, "{name}: only {published} publications");
        }
        if name == "timeout" || name == "stamps" {
            assert!(silent > 50, "{name}: only {silent} silent ticks");
        }
    }
}

/// The yaml still says what `mower()` says, and holds nothing this port
/// does not account for (the oracle vectors were made from it, so a change
/// there needs both regenerated).
#[test]
fn mower_params_match_the_yaml() {
    let path = format!("{}/../../../mower_nav2/config/nav2_no_map_params.yaml", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    let y: serde_yaml::Value = serde_yaml::from_str(&text).unwrap_or_else(|e| panic!("{path}: {e}"));
    let vs = y["velocity_smoother"]["ros__parameters"].as_mapping().unwrap();
    let mut keys: Vec<&str> = vs.keys().map(|k| k.as_str().unwrap()).collect();
    keys.sort_unstable();
    assert_eq!(
        keys,
        [
            "bond_heartbeat_period", // lifecycle bond: not ported
            "deadband_velocity",
            "enable_stamped_cmd_vel", // TwistStamped in and out: the IO layer
            "feedback",               // OPEN_LOOP, the only mode ported
            "max_accel",
            "max_decel",
            "max_velocity",
            "min_velocity",
            "odom_duration", // CLOSED_LOOP only
            "odom_topic",    // CLOSED_LOOP only
            "scale_velocities",
            "smoothing_frequency",
            "stamp_smoothed_velocity_with_smoothing_time",
            "velocity_timeout",
        ]
    );
    let get = |k: &str| &y["velocity_smoother"]["ros__parameters"][k];
    let arr = |k: &str| -> [f64; 3] {
        let a = get(k).as_sequence().unwrap();
        std::array::from_fn(|i| a[i].as_f64().unwrap())
    };
    assert_eq!(get("feedback").as_str(), Some("OPEN_LOOP"));
    assert_eq!(get("enable_stamped_cmd_vel").as_bool(), Some(true));
    let p = VelocitySmootherParams::mower();
    assert_eq!(get("smoothing_frequency").as_f64(), Some(p.smoothing_frequency));
    assert_eq!(get("scale_velocities").as_bool(), Some(p.scale_velocities));
    assert_eq!(
        get("stamp_smoothed_velocity_with_smoothing_time").as_bool(),
        Some(p.stamp_smoothed_velocity_with_smoothing_time)
    );
    assert_eq!(arr("max_velocity"), p.max_velocity);
    assert_eq!(arr("min_velocity"), p.min_velocity);
    assert_eq!(arr("max_accel"), p.max_accel);
    assert_eq!(arr("max_decel"), p.max_decel);
    assert_eq!(arr("deadband_velocity"), p.deadband_velocity);
    assert_eq!(get("velocity_timeout").as_f64(), Some(p.velocity_timeout));
}
